function findWords(board, words) {
  const m = board.length, n = board[0].length;
  const found = new Set();
  function checkWord(word) {
    function dfs(r, c, k) {
      if (k === word.length) return true;
      if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] !== word[k]) return false;
      const saved = board[r][c];
      board[r][c] = "#";
      const res = dfs(r + 1, c, k + 1) || dfs(r - 1, c, k + 1) || dfs(r, c + 1, k + 1) || dfs(r, c - 1, k + 1);
      board[r][c] = saved;
      return res;
    }
    for (let i = 0; i < m; i++) {
      for (let j = 0; j < n; j++) {
        if (dfs(i, j, 0)) return true;
      }
    }
    return false;
  }
  for (let w = 0; w < words.length; w++) {
    if (checkWord(words[w])) {
      found.add(words[w]);
    }
  }
  return Array.from(found).sort();
}

function findWords(board, words) {
  const root = {};
  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    let node = root;
    for (let j = 0; j < word.length; j++) {
      const ch = word[j];
      if (!node[ch]) node[ch] = {};
      node = node[ch];
    }
    node.word = word;
  }
  const m = board.length, n = board[0].length;
  const result = [];
  function dfs(r, c, parent) {
    const ch = board[r][c];
    const currNode = parent[ch];
    if (!currNode) return;
    if (currNode.word) {
      result.push(currNode.word);
      currNode.word = null;
    }
    board[r][c] = "#";
    if (r + 1 < m && board[r + 1][c] !== "#") dfs(r + 1, c, currNode);
    if (r - 1 >= 0 && board[r - 1][c] !== "#") dfs(r - 1, c, currNode);
    if (c + 1 < n && board[r][c + 1] !== "#") dfs(r, c + 1, currNode);
    if (c - 1 >= 0 && board[r][c - 1] !== "#") dfs(r, c - 1, currNode);
    board[r][c] = ch;
  }
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (root[board[i][j]]) {
        dfs(i, j, root);
      }
    }
  }
  return result.sort();
}

def findWords(board: list[list[str]], words: list[str]) -> list[str]:
    m, n = len(board), len(board[0])
    found = set()

    def check_word(word: str) -> bool:
        def dfs(r: int, c: int, k: int) -> bool:
            if k == len(word):
                return True
            if r < 0 or r >= m or c < 0 or c >= n or board[r][c] != word[k]:
                return False
            saved = board[r][c]
            board[r][c] = "#"
            ok = (
                dfs(r + 1, c, k + 1)
                or dfs(r - 1, c, k + 1)
                or dfs(r, c + 1, k + 1)
                or dfs(r, c - 1, k + 1)
            )
            board[r][c] = saved
            return ok

        for i in range(m):
            for j in range(n):
                if dfs(i, j, 0):
                    return True
        return False

    for word in words:
        if check_word(word):
            found.add(word)
    return sorted(found)

def findWords(board: list[list[str]], words: list[str]) -> list[str]:
    root = {}
    for word in words:
        node = root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = word

    m, n = len(board), len(board[0])
    result = []

    def dfs(r: int, c: int, parent: dict) -> None:
        ch = board[r][c]
        curr_node = parent.get(ch)
        if not curr_node:
            return
        if "$" in curr_node:
            result.append(curr_node.pop("$"))
        board[r][c] = "#"
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] != "#":
                dfs(nr, nc, curr_node)
        board[r][c] = ch

    for i in range(m):
        for j in range(n):
            if board[i][j] in root:
                dfs(i, j, root)

    result.sort()
    return result
